SELECT *, SUM(balance) OVER (PARTITION BY account_type ORDER BY opened_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_balance, MIN(balance) OVER (PARTITION BY account_type ORDER BY opened_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_balance, COUNT(balance) OVER (PARTITION BY account_type ORDER BY opened_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_balance, MIN(balance) OVER (PARTITION BY customer_id) AS customer_id_min_balance FROM accounts WHERE customer_id IN (13, 24);
